def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = [
        (lambda r, c: r),
        (lambda r, c: c),
        (lambda r, c: r + c),
        (lambda r, c: r - c),
    ]

    for key_fn in candidates:
        lines = {}
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 0:
                    lines.setdefault(key_fn(r, c), []).append((r, c, grid[r][c]))

        if not lines:
            continue

        valid = True
        for key, cells in lines.items():
            color = cells[0][2]
            if any(v != color for _, _, v in cells):
                valid = False
                break
            expected = sum(
                1 for r in range(h) for c in range(w)
                if key_fn(r, c) == key
            )
            if len(cells) != expected:
                valid = False
                break
        if not valid:
            continue

        colors_by_key = {key: cells[0][2] for key, cells in lines.items()}
        lo, hi = min(colors_by_key), max(colors_by_key)
        period = None
        mapping = None

        for p in range(1, hi - lo + 2):
            trial = {}
            consistent = True
            for key, color in colors_by_key.items():
                residue = key % p
                if residue in trial and trial[residue] != color:
                    consistent = False
                    break
                trial[residue] = color
            if consistent and len(trial) == p:
                period, mapping = p, trial
                break

        if period is not None:
            return [
                [mapping[key_fn(r, c) % period] for c in range(w)]
                for r in range(h)
            ]

    return [row[:] for row in grid]
